/* FGC Membership Portal - certificate & covenant
   Draws the fixed church designs (backgrounds from your PDFs) and fills in the member's name and date.
   Used by app.js:  FGCDocs.draw(canvas, 'cert' | 'cov', { name, id, joined })  ->  Promise
   Everything (pictures + fonts) is inside this one file. */
(function () {
  var BG = { ded: 'data:image/jpeg;base64,', bapt: 'data:image/jpeg;base64,', cert: 'data:image/jpeg;base64,', cov: 'data:image/jpeg;base64,' };
  var FONTS = [
    ['FGC Pagella', '400', ''],
    ['FGC Pagella', '700', ''],
    ['FGC Courgette', '400', ''],
    ['FGC Gelasio', '700', '']
  ];
  var W = 2200, H = 1700, S = W / 792;            // page is 11 x 8.5 in (792 x 612 pt); S = pixels per point
  var MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];

  var fontsP = null, imgs = {};
  function loadFonts() {
    if (!fontsP) fontsP = Promise.all(FONTS.map(function (f) {
      var ff = new FontFace(f[0], 'url(data:font/woff2;base64,' + f[2] + ')', { weight: f[1] });
      return ff.load().then(function (x) { document.fonts.add(x); });
    }));
    return fontsP;
  }
  function loadImg(k) {
    if (!imgs[k]) imgs[k] = new Promise(function (res, rej) { var i = new Image(); i.onload = function () { res(i); }; i.onerror = function () { rej(new Error('background picture failed to load')); }; i.src = BG[k]; });
    return imgs[k];
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || ''), d = m ? new Date(+m[1], +m[2] - 1, +m[3]) : (s ? new Date(s) : new Date());
    return isNaN(d) ? new Date() : d;
  }
  function ord(n) { var v = n % 100; if (v >= 11 && v <= 13) return 'th'; return ({ 1: 'st', 2: 'nd', 3: 'rd' })[n % 10] || 'th'; }

  // set the font in points (page scale)
  function font(ctx, pt, fam, w, k) { ctx.font = w + ' ' + (pt * S * (k || 1)) + 'px "' + fam + '"'; }
  // centered name that shrinks to fit
  function fitName(ctx, text, cx, base, maxW, pt, minPt, fam, w, color) {
    var p = pt; font(ctx, p, fam, w);
    while (ctx.measureText(text).width > maxW * S && p > minPt) { p -= .5; font(ctx, p, fam, w); }
    ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.fillText(text, cx * S, base * S);
  }
  // draw a row of differently-styled pieces. pieces: [text, pt, family, weight, raisePt]
  function rowWidth(ctx, pieces, k) {
    var w = 0; pieces.forEach(function (p) { font(ctx, p[1], p[2], p[3], k); w += ctx.measureText(p[0]).width; }); return w;
  }
  function drawRow(ctx, pieces, x, base, k, color) {
    ctx.fillStyle = color; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    pieces.forEach(function (p) { font(ctx, p[1], p[2], p[3], k); ctx.fillText(p[0], x, base * S - (p[4] || 0) * S); x += ctx.measureText(p[0]).width; });
  }

  // "On the 18th day of October in the year of our Lord, 2026 and is entitled ... member"
  function certDateRow(d) {
    var SC = ['FGC Courgette', '400'], GB = ['FGC Gelasio', '700'], PB = ['FGC Pagella', '700'];
    return [
      ['On the ', 12, SC[0], SC[1]], [String(d.getDate()), 14, GB[0], GB[1]], [ord(d.getDate()), 9, PB[0], PB[1], 1.6], [' day', 12, PB[0], PB[1]],
      [' of ', 12, SC[0], SC[1]], [MONTHS[d.getMonth()], 14, SC[0], SC[1]], [' in the year of our Lord, ', 12, SC[0], SC[1]],
      [String(d.getFullYear()), 16, GB[0], GB[1]], [' and is entitled to all rights and privileges of a member', 12, SC[0], SC[1]]
    ];
  }

  function drawCert(ctx, d) {
    var name = (d.name || '').trim(), date = parseDate(d.joined);
    fitName(ctx, name, 396, 208, 560, 30, 14, 'FGC Pagella', '700', '#141414');
    // size is fixed from the reference date so every certificate looks the same
    var ref = certDateRow(new Date(2026, 9, 18)), k = (553 * S) / rowWidth(ctx, ref, 1);
    var row = certDateRow(date), w = rowWidth(ctx, row, k), maxW = 600 * S;
    if (w > maxW) { k *= maxW / w; w = rowWidth(ctx, row, k); }
    drawRow(ctx, row, 398 * S - w / 2, 387.4, k, '#000');
  }

  function drawCov(ctx, d) {
    var name = (d.name || '').trim(), date = parseDate(d.joined);
    fitName(ctx, name, 396, 235, 560, 22, 12, 'FGC Pagella', '700', '#141414');
    fitName(ctx, name, 181.5, 531.3, 160, 10.5, 7, 'FGC Pagella', '700', '#000');
    var n = date.getDate();
    drawRow(ctx, [['dedication, this ' + n + ord(n) + ' day of ' + MONTHS[date.getMonth()] + ' ' + date.getFullYear() + ' at Davao City, Philippines.', 10, 'FGC Pagella', '400']], 36.4 * S, 480.2, 1, '#000');
  }

  // Certificate of Baptism: fills the blank lines of the church's baptism certificate (positions in points, page 792 x 612)
  function drawBapt(ctx, d) {
    var date = parseDate(d.joined), P = 'FGC Pagella', ink = '#141414';
    fitName(ctx, (d.name || '').trim().toUpperCase(), 396, 231, 420, 22, 12, P, '700', ink);
    if (d.birthday) { var b = parseDate(d.birthday); fitName(ctx, (MONTHS[b.getMonth()] + ' ' + b.getDate() + ', ' + b.getFullYear()).toUpperCase(), 411, 279, 250, 13, 9, P, '400', ink); }
    var n = date.getDate();
    fitName(ctx, n + ord(n), 230, 351, 84, 13, 9, P, '400', ink);
    fitName(ctx, MONTHS[date.getMonth()].toUpperCase(), 372, 351, 104, 13, 8, P, '400', ink);
    fitName(ctx, String(date.getFullYear()), 605, 351, 78, 13, 9, P, '400', ink);
    fitName(ctx, 'DAVAO CITY FOURSQUARE GOSPEL CHURCH', 405, 373, 380, 13, 8, P, '400', ink);
    if (d.minister) fitName(ctx, String(d.minister).trim(), 371, 445, 320, 13, 8, P, '400', ink);
  }

  // Certificate of Dedication (baby): fills the blank lines of the church's dedication certificate
  function drawDed(ctx, d) {
    var date = parseDate(d.joined), P = 'FGC Pagella', ink = '#141414', n = date.getDate();
    fitName(ctx, (d.name || '').trim().toUpperCase(), 396, 239.5, 420, 22, 12, P, '700', ink);
    if (d.birthday) { var b = parseDate(d.birthday); fitName(ctx, MONTHS[b.getMonth()] + ' ' + b.getDate() + ', ' + b.getFullYear(), 401, 295.5, 250, 14, 9, P, '400', ink); }
    fitName(ctx, n + ord(n), 225, 389.7, 76, 13, 9, P, '400', ink);
    fitName(ctx, MONTHS[date.getMonth()], 380, 389.7, 70, 13, 8, P, '400', ink);
    fitName(ctx, String(date.getFullYear()), 596, 389.7, 76, 13, 9, P, '400', ink);
    if (d.minister) fitName(ctx, String(d.minister).trim(), 450, 469.7, 280, 13, 8, P, '400', ink);
  }

  window.FGCDocs = {
    draw: function (cv, kind, d) {
      d = d || {}; kind = kind === 'cov' ? 'cov' : kind === 'bapt' ? 'bapt' : kind === 'ded' ? 'ded' : 'cert';
      return Promise.all([loadFonts(), loadImg(kind)]).then(function (r) {
        cv.width = W; cv.height = H;
        var ctx = cv.getContext('2d');
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
        ctx.drawImage(r[1], 0, 0, W, H);
        (kind === 'cov' ? drawCov : kind === 'bapt' ? drawBapt : kind === 'ded' ? drawDed : drawCert)(ctx, d);
      });
    }
  };
})();